BEGIN;

SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (575::BIGINT, 'El mejor y quizás único buen profe de la rama de Ingeniería de Software. Si tiene el chance tiene que llevar con este mae. Demasiado conocedor, demasiado ingenioso con sus actividades, y uno aprende un montón de cosas que de otro modo serían aburridísimas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '17cd17f561f37b5bcdf8c392f4bd55e4d1b906c3f3d76761966e5019dd4e6d48'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Un excelente profesor que lo hace a uno amar el curso. Aprendí demasiado con el profe Mauricio y le enseña mucha calle para el trabajo. No dude de matricular con el'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, '06314f7317c85f9d17dab1ab8a3aad045058c27d939a25f12288512bb4d30fef'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Uno pasa leyendo todo el curso, el proyecto no es programado es solo docu y se hacen muchos roleplays. El profe cae bien, sabe mucho y comparte su entusiasmo. Un único examen oral al final pero es grupal, entonces prepárense bien para que todos en el grupo tengan una buena nota. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2026-01-20T00:00:00+00:00'::TIMESTAMPTZ, '9df1df04a8f5594a90957db57e8b8361eeea3d6582b12391f18860ac5a525bc1'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Matriculen con él, de los mejores profes de compu honestación, demasiado carga y sabe demasiado, es algo pesado pero se logra. No es obligatoria la asistencia, pero aplicaba quiz en la mayoría de las clases y no avisa'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a6217a254d991411c7be3dd6704c41ddf72b117839f231d8983d7a68ef4942f2'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Es divertido ir a escuchar al profe, se aprende mucho con los "debates" que hacemos en clase. Varias lecturas al principio y al final un simposio. Se siente un poco más de 2 créditos, pero al final del semestre es muy flexible.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Inspirador']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '443fc8c9178c015506adaa70238d1b7e92074fbaa1b45ed4e28e5c754fc17c2b'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Es una clase tipo seminario, varias lecturas a la semana. No debes faltar porque se discuten lecturas en la clase y también deja ensayos. La redacción es importante. El profe la mayoría de clases hablará temas sociales y tecnológicos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'af471f503fd6ff74df2207801b7d57fede4b5d673c4d1b726715f431a89f61d6'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Hizo un quiz por semana virtual que es fácil. Un proyecto durante todo el semestre con entregas como cada 15 días. No se programa. La participación vale puntos. Pregunte mucho porque a veces no se sabe lo que quiere en una entrega a menos que pregunten en clase. Elija bien el grupo. Se puede pasar.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e634cfe6cbe8ba51253787d37118528f76ae3209eec1fd3c55301e0249b510c7'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El profe es súper ordenado con la clase y las evaluaciones, se le nota que le apasiona el tema. El proyecto se desarrolla a lo largo de todo el semestre por lo que cada 15 días puede que tenga que entregar cosas, sin embargo es cuestión de ordenarse. Volvería a matricular con él'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '21c48db746ab5b5ec33b9948d0a6bb09cf0a114034644076d4516e83d9bacf39'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Matriculen con él, de los mejores profes de compu!!! Si es bastante carga, pero se logra, además se sale en semana 16. No es obligatoria la asistencia, pero aplicaba quiz en la mayoría de las clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3d2e19aaa456b2ec1c73698511c8dfaf88e90afe73d15fcfc1b52cdb91d87d4e'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Las clases son excelentes, uno se mantiene muy atento y tiene que participar porque vale puntos. Responde consultas y siento que no califica rudo, aunque sí pone desde el inicio a gente entre cejas y a otros de favoritos. Hay muchas entregas y es pesado, pero el curso vale la pena: 100% recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'fee7a23c8a004076938b3145b1a4f3e0196326840bf589354240af85a28a2ecf'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El profe es bueno, pero es muy preferencial con las personas. Un grupo puede tener el mismo error que otro, que a uno le puede poner un 70 y otro un 90. Le gusta que participen (Hay que hacerlo para tenerlo contento), sus clases son buenas y como punto malo es ambiguo con preguntas y evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, '013c55b6e08a7cb266dacfe32fd593f7cad687f002d9da395415a600a6f3dadb'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Excelente profe! Hace que el curso sea entretenido y súper claro. Trabaja con el método aula invertida, por lo que hay que leer antes de llegar a la clase pero vale totalmente la pena pues se entienden mejor los conceptos. Las asignaciones son acordes a la materia que se ha visto.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '0b1886e38ef6fce4392f9253367a4ee8b7776b5da594f8ca3a7420a53a4ca953'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Es un excelente profe y hace que la materia llegue a ser interesante. Puede volverse pesado por la cantidad de trabajos, se recomienda tener un buen grupo de trabajo. La participación es muy importante (pide camara cuando se vaya hablar). Al final pide un mini proyecto que puede ser muy tedioso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'd915696fd9aca93341318d6732edebfe71b6e29573bceb6c32a43227e5b872ee'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Es; sin duda, el mejor profe que tiene la escuela de compu, se nota que tiene vocación y da las clases desde el marco del respeto, el curso se vuelve un poco pesado por la cantidad de trabajos pero son muy sencillos y se disfrutan bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-12-11T00:00:00+00:00'::TIMESTAMPTZ, '1c5351ee76214d149328751c918f43d8f130be57bad9979821250269884913c1'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Las clases son muy largas, pero suelen ser entretenidas. Deja bastantes trabajos, pero todos son muy fáciles y se logran sacar si uno es bien organizado. El profesor cae bien y no es muy estricto a la hora de calificar. De los mejores profes de la Escuela de Computación.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases largas']::TEXT[], '2022-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ad6338bf5dc7e5f4484fd462c9e7451452a68fbff802a79e2da2d847e79c81bc'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Es un buen profesor, bastante amable. Si se acoplan al ritmo de trabajo del profesor no deberia haber problema para aprobar el curso. Si lo recomiendo bastante!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '1dccc3377244d33d3701d35c29df1a6ae4e5c1f021683d827db1e359bdedf814'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'La clase es demandante en el sentido de que es mucha materia, el profesor ayuda mucho y da muy buena retroalimentación sin embargo es importante mantenerse al día porque si uno se atrasa es muy díficil recuperar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0e092182735263fe7956488dfe3eb97de92a5af082c3d9b81813c8d1c4483979'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Es muy buen profe, aunque hay que estar participando en clase y no indica cuales son los puntos a evaluar en las entregas entonces baja puntos a lo que caiga. En general es bueno, si quiere practicar reuniones con clientes y asi matricule con el'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a0bacf920789e0102aecefc831138568eb6560a1c431978801fc51fe2c1c97ca'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'En general es buen profe. Sin embargo, el curso se vuelve excesivamente teórico con las lecturas larguísimas que deja, tiene una manía por pedir la cámara en clase cuando es virtual y al final se hace un proyecto de acción social. Demasiada carga para un curso de 2 créditos.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9be44b4603ea526fe403b5995e43ef7942d974fadecaa0205eb5a2b7d42aec09'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-26T00:00:00+00:00'::TIMESTAMPTZ, 'bcbd49050101fd5688e27b32894fc47fce3dcef72967ecbf777a54aa10a2ece8'::TEXT, ARRAY[4871, 4867]::BIGINT[]),
    (575::BIGINT, 'El curso no es facil, es bastante cansado, es todo el semestre un trabajo en grupo, pero es de los cursos más productivos que he tenido, se aprende demasiado y le dan a uno ganas de siempre participar, hay un ambiente de confianza, sumamente recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f04c092fc6a93d8b3b4ec0d0a4c05cb936a2f8c44074a9ccc5625999f29ff9bb'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Es uno de los mejores profesores que se va a topar en la carrera, pero no deja de ser un poco pesado el curso. Se nota que le gusta enseñar y hacer que los estudiantes salgan de su zona de confort para que así puedan aprender más. La verdad lo recomiendo bastante, aunque sea duro calificando.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'fad173b1769393e9bd49810b30172361e877ef9a728fddaadb53e48eda4888e0'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Excelente profesor, el curso está muy bien organizado y se sale en semana 16. El profesor tiene muchísimo conocimiento y sabe cómo transmitirlo mientras se preocupa porque el estudiante realmente aprenda. Excelente ser humano y profesional, de los pocos profes que realmente tienen vocación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4ed6a38832ebd5cad7f63f6e2589f7b3c56dd6cb4cb06c40609ad72ea6658111'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Es muy buen profe, explica super bien, pero a veces no es tan claro con lo que solicita, además que los quiz los califica bastante duro ya que si no dice exactamente lo que él quiere, entonces esta mal. Pero en general un profe muy recomendable. Además da puntos por participar en la clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '3cc97ca2ed2180cdb8fb327e9508b1eb2100c9b974af8f4bbbaace94b4d56133'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Excelente profe, le interesa que uno aprenda, busca que las clases nos sean aburridas, los trabajos son sencillos y están bien distribuidos a lo largo del semestre, 100% recomendado llevare este curso con él, aprenderá cosas que jamás se imagino'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '5de9662a2e5b26310f731cde3d3fe96ad772ae1029b8e85f526cc660bda6b10f'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Excelente profe, el proyecto se divide en varias partes, hace quiz todas las semanas, clases dinámicas y entretenidas. Se preocupa por que sus estudiantes entiendan y mejoren sus habilidades. SUPER RECOMENDADO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '97aed8ac2522b59cd6fe778e1e182b1bd59ac8d09e7b8b865f915f8d814565f3'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'De los mejores profes que me he encontrado, un curso muy orientado al mundo real, el proyecto esta dividido en varias etapas que se revisan a través de auditorías, el profe esta atento a dudas en clase y fuera de ella, quiz casi todas las semanas, el curso esta bastante organizado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '9b4c85c412f33e4649da41e4d786fc7d28c9e635b608cbc301734e96c4b1254c'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Da las clases muy bien, pero son bastante pesadas, pide mucha participación de los estudiantes. Los trabajos son grupales y los grupos son aleatorios así que puede ser un problema. Honestamente un curso con él es excelente pero MUY cansado. Si faltan muchos a la clase hace evaluación'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'e481190a9f26149e414674cc550e887675e55a74a3f94ac9ab61e4efd40e204a'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Es un excelente profe, está siempre pendiente de si uno necesita ayuda con algo, explica súper bien, eso sí, los trabajos hay que pensarlos bien y esmerarse, recomiendo revisarlos con él antes de entregarlos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-04-29T00:00:00+00:00'::TIMESTAMPTZ, '18b26d05d5b5380ee5f9038a7f6890905967683b74477da26fe9ff3fa3c40f5a'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El profe sabe mucho e intenta hacer las clases interesantes. Se hacen lecturas semanales que son bastante buenas y se discuten en clases. Se hace un proyecto en grupos que consta de 5 entregas y un examen final. En general es bastante bueno y se sale en semana 16.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '4d658d722e0bc69274987ba18d9904d53f02facee5acf532f1399d46cca15b04'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Las clases son excelentes, eso sí, deja demasiados trabajos, la mayoría son muy largos y los grupos de trabajo son al azar, entonces puede ser un dolor. Se aprende bastante y para semana 16 ya se entregaron todos los trabajos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '2035abfd3968c01451dafbc3ef8f1f291cd4e45db44ed8c074777b6e96cbc7c2'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Realmente la cantidad de trabajos y el tiempo que da para cada uno es para que desde que se deja tiene que empezar a bretearle porque es largo y medio complicado y deja, básicamente 1 cada 2 semanas por lo que la van a pasar mal.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'd783678e9ef877b88ff4990f22060b0a6a1241cc01571ae4876373548d9fed3f'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Deja trabajos muy largos, en muy poco tiempo se espera que avances un monton. Explica bien, deja buen material pero hay una cantidad excesiva de trabajos a lo largo del proyecto, tome en cuenta que cuenta por 10 creditos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2020-12-15T00:00:00+00:00'::TIMESTAMPTZ, '1faa12d595fb877983fdb7e16f4552323e66e0cfedaacb18b5484000aae0b370'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Da poco tiempo para todo, bastante intenso con feedback.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-12-15T00:00:00+00:00'::TIMESTAMPTZ, '9f00b179526ab37c5dd53da1816315f0f5c7b24933b24e81f855906085c510f7'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Exc profe de esos pocos con los q vos llevarías toda la carrera. Ama dar AP y siempre está innovando el curso. Yo lo cursé en 2019 y ya probaba con algunas clase virtuales. En facilidad puse 4/5 xq el curso es fácil pero hay que trabajar todas las semanas. Si llevás AP con el te encantará el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '0d31ebc8ad4699ad91a6070bea31ba2aab11e7745fa6739b758b48e23784b903'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Excelente profe, tiene las clases muy bien organizadas. Hay que leer todas las semanas para poder hacer los quices, las clases requieren bastante participación de los estudiantes y trata de hacerlas lo más interactivas posibles.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '67d62abd5d921df94f8ea386a842a00970d6b222e2f345126879ccf50e7ecf21'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Una maravilla de profesor, ama lo que hace, adora el curso, tiene las clases planeadas y sabe muy bien si la clase está entendiendo o no. Se toma su tiempo de preguntarle a la gran mayoría de la clase algo respectivo al tema que se esté viendo para hacer un resumen para comprobar el entendimiento.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '8053e60c50c7235bfd9d1f6b47f768a616cdea5a37fdff5bef96012420bd81aa'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Es excelente en este campo, va a aprender un montón. Las clases son muy dinámicas al haber mucha participación en clase. Se hacen varios trabajos en grupo que son fáciles si uno va haciendo las lecturas diarias y pone atención. Me gustó su método de enseñanza por lo que pienso llevar AP con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '2a3282d248cd61f49235888b14b6bbd16b909234c976c59f4d7baf0a935a6c62'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Da las clases de una forma muy diferente a los demás profes, pero hace que uno no se aburra, hay que leer para una de las clases de la semana porque hace quiz, pero si lee va a saber resolverlo. Si puede meter con él hagalo, es de los mejores profes que hay de compu.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'fb4d145d76012965fd6fd21784871c848245fb8cf87c7b37e6cfe88395d83fa8'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Excelente profe, de los mejores profes de compu. Explica muy bien y únicamente lo que tiene que explicar, planea muy bien las clases, las evaluaciones no fueron tan pesadas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '6859f6e892ad5f8a366cac0ef7be1357cf9f000715e0e94943eb1083c04edfc6'::TEXT, ARRAY[1039]::BIGINT[]),
    (575::BIGINT, 'Es un excelente profesor que se preocupa por el desarrollo del estudiante. Es bastante selectivo y si algo no le gusta se lo va a decir. Las clases pueden ser un poco aburridas con horarios feos y el volumen de la materia es exagerado, pero el curso tampoco es imposible.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases largas']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'e264fe9d9cb6ae5125a2345fa5925838c7b394008ca2036b3a2d7b1fc661e7b0'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El curso lo hace interesante , lo equilibra bastante bien para que no afecte en el semestre , lo hace a uno reflexionar un poco y genera un debate ameno sobre los temas ,hay que participar en clases y hacer las tareas y se pasa facil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '720c240260da91de951e1e92316bbfe2b65392094975da5dc829f6cde4a0f716'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'El profesor hace que el curso no sea tan aburrido como podría ser. Da una buena perspectiva y fomenta el debate. Muchas asignaciones para un curso de 2 créditos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'fdc6536ee82066e52dc38916b7e53ba7a3d2bf2259ed79a0d7191ab7ff889d2b'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'Las clases son interesantes, ayudan a tener una perspectiva diferente sobre algunos temas. Sin embargo, la cantidad de trabajos y carga académica es muy desproporcional para un curso de 2 c?editos'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Clases largas']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '604097241969858d5b6b44be1eb1599ef0e68a80c5b773b00b8e6cfe084ec69e'::TEXT, ARRAY[1156]::BIGINT[]),
    (575::BIGINT, 'La clase es excelente, explica todo con claridad. Donde falla es en la calificación, suele ser arbitraria y notas de gran peso se ven afectadas por individuos irresponsables de grupos que son creados de manera aleatoria.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-07-03T00:00:00+00:00'::TIMESTAMPTZ, '6439dc5feac643a8e68228d38beea56c5cf44c10c31d25a88d12231baa3bc0e9'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El profe cae bien, explica bien la materia, mas que es su area, pero sus metodos de calificacion no son buenos para nada,con solo de que en su grupo haya alguien irresponsable les afecta en la nota al resto y los grupos son aleatorios y los quices son demasiado imporantes, cosa que no deberia de ser'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd6929827a8696ad1ac78961735b209cc3d670dd43acc0c989c70a30e4ac902fc'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El mae penaliza a todas las personas del equipo si no se presenta un integrante a la revisión, nunca especifica qué quiere, simplemente el peor profe, si le toca un curso con él póngale a pasar para no verlo nunca más.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '34b6c455e03e0b875266c23bdf058d4c46a2209147169304a921f4d4a19e37a9'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Aunque el curso tenga mucha materia, el profe se esfuerza para que esta sea interesante y uno quiera poner atencion. Le interesa mucho que la documentacion este muy bien hecha y lo expone a uno a una simulacion con un supuesto cliente real, lo cual me parece muy provechoso. El examen medio dificil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '77e5857609fd219bead62d3438f8ce899e5bcc6a6025f01ce6c029b4d0d0c61f'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'El profe explica muy bien la materia, y es muy fácil. Hay muchos quices a lo largo del semestre y tienen bastante valor, pero son sencillos. Solo hace un examen al final. Un solo proyecto grupal para el que se hacen muchos trabajos durante el semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9671c55e2e3f08bbb02b1e69b00c651ec0f25f4c009db9c50f01105a3b6dc263'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Me gustó mucho el curso, le interesa que los estudiantes aprendan ciertos aspectos que son más de "calle", no tanto memorístico. Los quices eran muy de memorizar (cda semana), sin embargo el examen era mucho de lo que el profe decía en clase, ojo, presten mucha atención.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c861183352d03a57caaeb61bf20ac116455905b32627317873184229fc50731f'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Se quiere hacer el buen profesor, pero baja puntos por cualquier cosa. No explica bien qué quiere que uno le entregue en las auditorias. Su clase se basa en presentaciones de power point infinitas que después tendrás que aprenderte para el examen final.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '44aa540cc53801ca77a90c75eb7067b34afffa4c232d5095c3d68982c12f6c16'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Se pasa bien si logra pesar como él quiere que usted piense. Un examen final que más que un examen parecía un "qué respondería el profe acá". Él habla de lo importante que es alejarse de las perfectivas a la hora de resolver problemas pero ni lo demuestra en la práctica.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '0cea34f58ad34f476f0c010efd70e873973335a13efad8f9cb5aadcf66449e1a'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Calificacion subjetiva, ayuda solo si se le pide o si es en extremo necesario'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, '1095e19256a0e1dca0cf738a1e519a76cb8cb252e0ea9f090fb91715a087862e'::TEXT, ARRAY[1052]::BIGINT[]),
    (575::BIGINT, 'Excelente profesor, muy recomendado, es un coach nato.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '7bd64d7c7fb764755362d3f53252d66a8431b13cfe96131dfeec46e29753db99'::TEXT, ARRAY[21]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
